from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class PMv2HttpClient(HttpClient):
    """ This class provides a client for the PM V2 API. """

    def __init__(self, base_url, connection_alias):
        super(PMv2HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/pm/v2"

    def get_counter_objects(self, counter_id, timeout=30):
        endpoint = f'/counters/{counter_id}/objects'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_measurements(self):
        endpoint = '/measurements'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers)

    def get_counter(self, counter, timeout=30, **kwargs):
        endpoint = '/counters/values'
        headers = {
            "Content-Type": "application/json",
        }
        data = {
            "counter": counter,
            "startTimeLowerLimit": kwargs.get('start_time_lower_limit'),
            "startTimeUpperLimit": kwargs.get('start_time_upper_limit')
        }

        return self._send_get_request(endpoint=endpoint, payload=data, timeout=timeout, headers=headers)

    def get_counter_info(self, counter_id):
        endpoint = f"/counters/{counter_id}/info"
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers)
